CREATE FUNCTION salud_u.reporte_clinico(p_filtros jsonb) RETURNS TABLE(encounter_id uuid,closed_at timestamptz,encounter_type text,specialty_name text,carnet text,patient_name text,chief_complaint text,assessment text,instructions text,diagnoses text,allergies text,background_summary text,habits jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$
DECLARE desde date:=nullif(p_filtros->>'from','')::date; hasta date:=nullif(p_filtros->>'to','')::date; tipo text:=nullif(p_filtros->>'encounterType',''); especialidad uuid:=nullif(p_filtros->>'specialtyId','')::uuid; termino text:=nullif(lower(btrim(coalesce(p_filtros->>'search',''))),''); diagnostico text:=nullif(lower(btrim(coalesce(p_filtros->>'diagnosis',''))),''); personal uuid:=salud_u.id_mi_personal_activo();
BEGIN
 IF desde IS NOT NULL AND hasta IS NOT NULL AND desde>hasta THEN RAISE EXCEPTION 'RANGO_FECHAS_INVALIDO' USING ERRCODE='22023'; END IF;
 IF tipo IS NOT NULL AND tipo NOT IN('INITIAL','SPECIALTY') THEN RAISE EXCEPTION 'TIPO_ENCUENTRO_INVALIDO' USING ERRCODE='22023'; END IF;
 IF NOT(salud_u.tiene_rol_actor('ADMINISTRATIVE') OR salud_u.tiene_rol_actor('REVIEW_DOCTOR') OR salud_u.tiene_rol_actor('SPECIALIST')) THEN RAISE EXCEPTION 'REPORTE_NO_AUTORIZADO' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT e.id,e.cerrado_en,e.tipo_encuentro,s.nombre,p.carnet,concat_ws(' ',p.nombres,p.apellidos),e.motivo_consulta,e.evaluacion,e.indicaciones,coalesce((SELECT string_agg(d.texto_libre,' · ' ORDER BY d.creado_en) FROM salud_u.diagnostico_encuentro d WHERE d.id_encuentro=e.id),''),coalesce(v.datos #>> '{allergies}',''),coalesce(v.datos::text,''),coalesce(f.datos->'habits','{}'::jsonb) FROM salud_u.encuentro_clinico e JOIN salud_u.paciente p ON p.id=e.id_paciente LEFT JOIN salud_u.especialidad s ON s.id=e.id_especialidad LEFT JOIN salud_u.version_antecedente_clinico v ON v.id=e.id_version_antecedente_clinico LEFT JOIN salud_u.ficha_revision_version f ON f.id_encuentro=e.id WHERE e.estado='CLOSED' AND (desde IS NULL OR e.cerrado_en::date>=desde) AND (hasta IS NULL OR e.cerrado_en::date<=hasta) AND (tipo IS NULL OR e.tipo_encuentro=tipo) AND (especialidad IS NULL OR e.id_especialidad=especialidad) AND (salud_u.tiene_rol_actor('ADMINISTRATIVE') OR (salud_u.tiene_rol_actor('REVIEW_DOCTOR') AND e.tipo_encuentro='INITIAL' AND e.id_personal=personal) OR (salud_u.tiene_rol_actor('SPECIALIST') AND e.tipo_encuentro='SPECIALTY' AND e.id_personal=personal)) AND (diagnostico IS NULL OR EXISTS(SELECT 1 FROM salud_u.diagnostico_encuentro d WHERE d.id_encuentro=e.id AND lower(d.texto_libre) LIKE '%'||diagnostico||'%')) AND (termino IS NULL OR lower(concat_ws(' ',e.motivo_consulta,e.evaluacion,e.indicaciones,s.nombre)) LIKE '%'||termino||'%') ORDER BY e.cerrado_en DESC,e.id;
END $$;
GRANT EXECUTE ON FUNCTION salud_u.reporte_clinico(jsonb) TO ${runtime_role};
